from model.base import BaseStrategy

class CountMaximalCocktailsCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.SMT

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        nodes_list = data['nodes']
        edges_list = data['edges']

        # Build adjacency list
        adj = {node: set() for node in nodes_list}
        for u, v in edges_list:
            adj[u].add(v)
            adj[v].add(u)

        # Generate all independent sets
        all_independent = []
        nodes_sorted = sorted(nodes_list)

        def backtrack(start, current):
            all_independent.append(current.copy())
            for i in range(start, len(nodes_sorted)):
                node = nodes_sorted[i]
                can_add = True
                for v in current:
                    if v in adj[node]:
                        can_add = False
                        break
                if can_add:
                    current.append(node)
                    backtrack(i+1, current)
                    current.pop()

        backtrack(0, [])

        # Filter to maximal sets
        maximal_sets = []
        all_nodes_set = set(nodes_list)

        def is_maximal(s):
            for v in all_nodes_set:
                if v not in s:
                    has_neighbor = False
                    for u in adj[v]:
                        if u in s:
                            has_neighbor = True
                            break
                    if not has_neighbor:
                        return False
            return True

        for s in all_independent:
            if is_maximal(s):
                maximal_sets.append(s)

        # Prepare the output
        if message.difficulty == 'easy':
            result = len(maximal_sets)
        else:
            result = [list(s) for s in maximal_sets]

        return_info = Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=result, type='custom')]
        )

        return return_info

